fast_pseudocode:
# CORRECT: lambda grid adapts to whichever XBLOCK autotune selects
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 256}, num_warps=8),
        triton.Config({'XBLOCK': 128}, num_warps=4),
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    ...

def kernel_function(*inputs):
    xnumel = 878080
    grid = lambda META: (triton.cdiv(xnumel, META['XBLOCK']),)  # dynamic
    kernel[grid](..., xnumel)
